import fs from 'node:fs';
const base = process.argv[2];
for (const f of process.argv.slice(3)) {
	const r = JSON.parse(fs.readFileSync(`${base}/${f}.receipt.json`, 'utf8'));
	console.log(`=== ${f}  state=${r.state} results=${(r.results || []).length}`);
	for (const x of r.results || [])
		console.log(`   R ${x.site?.file} ${(x.site?.semanticPath || []).join('/')} access=${x.access}`);
	for (const u of r.unresolved || [])
		console.log(`   U ${u.reason} :: ${u.site?.file} ${(u.site?.semanticPath || []).join('/')} :: ${u.detail}`);
}

