function calleeDescription(module: Module, call: RichNode): string {
	const callee = call.callee as RichNode | undefined;
	if (callee === undefined) return 'a call';
	const prefix = call.type === 'NewExpression' ? 'new ' : '';
	const rendered = calleeName(module, callee);
	return rendered === null ? 'an opaque callee' : `'${prefix}${rendered}'`;
}

function calleeName(module: Module, node: RichNode): string | null {
	if (node.type === 'Identifier') return node.name ?? null;
	if (node.type === 'ChainExpression')
		return node.expression === undefined
			? null
			: calleeName(module, node.expression as RichNode);
	if (node.type === 'MemberExpression') {
		const object = node.object === undefined ? null : calleeName(module, node.object as RichNode);
		const key = staticMemberKey(node);
		return object === null || key === null ? null : `${object}.${key}`;
	}
	return null;
}

